// Chapter 16 demo: reconstruction-error histogram + threshold slider -> sensitivity / specificity.
// Data: window.CH16_THRESHOLD_DATA (from ch16-threshold-data.js, generated by scripts/figs_ch16.py
// from the executed notebook). Counts are per log10(error) bin, so the threshold moves in bin steps.
// Rule: a beat is flagged abnormal when its error falls in a bin at or above the threshold edge.
function initCh16Threshold() {
  const el = document.getElementById("ch16-demo");
  if (!el) return;
  const data = window.CH16_THRESHOLD_DATA;
  if (!data || !window.Plotly) {
    el.textContent = "互動資料載入失敗，請重新整理頁面。";
    return;
  }
  const slider = document.getElementById("ch16-thr");
  const thrOut = document.getElementById("ch16-thr-val");
  const info = document.getElementById("ch16-info");
  const edges = data.bins, c = data.counts, nb = edges.length - 1;
  const sum = (a) => a.reduce((s, v) => s + v, 0);
  const abn = c.N.map((_, i) => c.S[i] + c.V[i] + c.F[i]);
  const totN = sum(c.N), totA = sum(abn);
  const centers = edges.slice(0, -1).map((e, i) => (e + edges[i + 1]) / 2);   // log10 scale
  const width = edges[1] - edges[0];
  const dens = (arr, tot) => arr.map((v) => v / tot / width);

  // default: the bin edge closest to the notebook's 95th-percentile threshold
  let k0 = 0;
  edges.forEach((e, i) => {
    if (Math.abs(e - Math.log10(data.threshold95)) < Math.abs(edges[k0] - Math.log10(data.threshold95))) k0 = i;
  });
  slider.min = 20; slider.max = 70; slider.step = 1; slider.value = k0;

  const tail = (arr, k) => sum(arr.slice(k));
  const pct = (a, b) => (b ? (100 * a / b).toFixed(1) + "%" : "—");

  function colors() {
    const s = getComputedStyle(document.body);
    return {
      fg: s.getPropertyValue("--md-default-fg-color").trim() || "#333",
      grid: s.getPropertyValue("--md-default-fg-color--lightest").trim() || "#ddd",
    };
  }

  function draw() {
    const k = parseInt(slider.value, 10);
    const thr = Math.pow(10, edges[k]);
    thrOut.textContent = thr.toFixed(3);
    const col = colors();
    const traces = [
      { x: centers, y: dens(c.N, totN), width: width, type: "bar", name: "N 正常類", marker: { color: "#607D8B" }, opacity: 0.6 },
      { x: centers, y: dens(abn, totA), width: width, type: "bar", name: "S／V／F 異常", marker: { color: "#F4511E" }, opacity: 0.6 },
    ];
    const layout = {
      barmode: "overlay", bargap: 0, height: 340, margin: { l: 55, r: 10, t: 10, b: 50 },
      paper_bgcolor: "rgba(0,0,0,0)", plot_bgcolor: "rgba(0,0,0,0)", font: { color: col.fg },
      xaxis: { title: "重建誤差（對數刻度）", range: [-2.6, 0.6], gridcolor: col.grid,
               tickvals: [-2, -1, 0], ticktext: ["0.01", "0.1", "1"] },
      yaxis: { title: "密度", gridcolor: col.grid, zeroline: false },
      legend: { x: 0.01, y: 0.98, bgcolor: "rgba(0,0,0,0)" },
      shapes: [{ type: "line", xref: "x", yref: "paper", x0: edges[k], x1: edges[k], y0: 0, y1: 1,
                 line: { color: col.fg, width: 2, dash: "dash" } }],
    };
    Plotly.react(el, traces, layout, { displayModeBar: false, responsive: true });
    const tp = tail(abn, k), fp = tail(c.N, k);
    const sensBy = ["S", "V", "F"].map((s) => s + " " + pct(tail(c[s], k), sum(c[s]))).join("、");
    info.innerHTML =
      "敏感度 <b>" + pct(tp, totA) + "</b>（" + sensBy + "）・ 特異度 <b>" + pct(totN - fp, totN) +
      "</b> ・ 被判異常的正常心搏 <b>" + fp.toLocaleString() + "</b> 個 ・ 抓到的異常心搏 <b>" +
      tp.toLocaleString() + "</b> / " + totA.toLocaleString() + " 個";
  }

  slider.addEventListener("input", draw);
  const obs = new MutationObserver(draw);
  obs.observe(document.body, { attributes: true, attributeFilter: ["data-md-color-scheme"] });
  draw();
}

if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", initCh16Threshold);
else initCh16Threshold();
